import { useRoute, useRouter } from 'vue-router'
import axios from 'axios'
import OperationsChart from '../components/OperationsChart.vue'
import AgentNetwork from '../components/AgentNetwork.vue'
const route = useRoute(), router = useRouter()
const api = axios.create({ baseURL: '/api/v1/operations', timeout: 30000 })
const data = ref(null), graph = ref({ nodes: [], edges: [] }), day = ref(''), days = ref(1), loading = ref(true), error = ref(''), busy = ref(false)
const hour = ref(12), timePlaying = ref(false), run = ref(null), runs = ref([]), strategy = ref('balanced'), selectedAgent = ref('quality'), replaying = ref(false), replayIndex = ref(0)
let timeTimer, replayTimer, requestId = 0
const section = computed(() => ({ '/agents': 'agents', '/scenarios': 'scenarios', '/carbon-analysis': 'carbon', '/data-center': 'data' })[route.path] || 'overview')
const page = computed(() => ({ overview: { code: 'OVERVIEW', title: '园区总览', description: '洞察能源脉动，让低碳决策从这里发生。' }, agents: { code: 'AGENT STUDIO', title: '协同智能，清晰可见', description: '七个专业 Agent，从原始数据到可审计的园区决策。' }, scenarios: { code: 'STRATEGY LAB', title: '推演低碳的更多可能', description: '改变能源配置，观察成本、排放与运行约束如何变化。' }, carbon: { code: 'CARBON & RESOURCES', title: '读懂园区的碳与资源', description: '以一致的核算口径，连接能源消耗、排放与资源循环。' }, data: { code: 'DATA FOUNDATION', title: '可信分析，从数据开始', description: '查看数据来源、资产边界与每一条小时记录。' } })[section.value])
const number = (n, digits = 1) => Number.isFinite(Number(n)) ? Number(n).toLocaleString('zh-CN', { minimumFractionDigits: digits, maximumFractionDigits: digits }) : '—'
const current = computed(() => data.value?.series[Math.min(hour.value, data.value.series.length - 1)] || {})
function spark(key) { const values = data.value.series.slice(-24).map(r => r[key]); const lo = Math.min(...values), range = Math.max(...values) - lo || 1; return values.map((v, i) => `${i / (values.length - 1) * 100},${26 - (v - lo) / range * 23}`).join(' ') }
const cards = computed(() => { const d = data.value.summary; return [
  { title: '园区用电量', value: number(d.load_mwh, 2), unit: 'MWh', icon: 'ϟ', note: '所选窗口 · 小时电量积分', spark: spark('load_kw') },
  { title: '可再生发电 / 用电比', value: number(d.renewable_ratio, 1), unit: '%', icon: '↗', note: '光伏 + 风电 / 负荷', spark: spark('pv_kw') },
  { title: 'Scope 1 + 2 排放', value: number(d.carbon_t, 2), unit: 'tCO₂', icon: '◌', note: '燃气与外购电 · 模拟因子', spark: spark('scope2_kg') },
