] })
const flowNodes = computed(() => [{ name: 'SOLAR / 光伏出力', value: current.value.pv_kw, x: 125, y: 75 }, { name: 'GRID / 电网净购电', value: current.value.grid_import_kw - current.value.grid_export_kw, x: 650, y: 75 }, { name: 'STORAGE / 储能净放电', value: current.value.discharge_kw - current.value.charge_kw, x: 125, y: 245 }, { name: 'LOAD / 园区负荷', value: current.value.load_kw, x: 650, y: 245 }])
const baseChart = { color: ['#a2e487', '#6dbbaa', '#e8cc86', '#9da6d9'], backgroundColor: 'transparent', textStyle: { color: '#81958d', fontFamily: 'Inter, Microsoft YaHei, sans-serif' }, tooltip: { trigger: 'axis', backgroundColor: '#162720', borderColor: '#3b5144', textStyle: { color: '#e5ede5' }, valueFormatter: value => number(value, 2) }, legend: { bottom: 0, textStyle: { color: '#97a79d', fontSize: 11 }, itemWidth: 14, itemHeight: 7 }, grid: { top: 22, left: 55, right: 20, bottom: 55 }, yAxis: { type: 'value', splitLine: { lineStyle: { color: '#22362c', type: 'dashed' } } } }
function lineChart(rows, specs) { return { ...baseChart, xAxis: { type: 'category', boundaryGap: false, data: rows.map(r => r.timestamp.slice(11, 16)), axisLine: { lineStyle: { color: '#2c4235' } }, axisTick: { show: false } }, series: specs.map((s, i) => ({ name: s.name, type: 'line', showSymbol: false, smooth: .25, lineStyle: { width: 2, type: s.dashed ? 'dashed' : 'solid' }, areaStyle: i === 0 ? { opacity: .07 } : undefined, data: rows.map(s.value) })) } }
const energyChart = computed(() => lineChart(data.value.series, [{ name: '光伏', value: r => r.pv_kw }, { name: '风电', value: r => r.wind_kw }, { name: '负荷', value: r => r.load_kw }, { name: '电网购电', value: r => r.grid_import_kw, dashed: true }]))
const states = computed(() => { const result = {}; for (const e of visibleEvents.value) result[e.agent] = e.status; return result })
const visibleEvents = computed(() => run.value?.events.slice(0, replayIndex.value) || [])
const selectedNode = computed(() => graph.value.nodes.find(n => n.id === selectedAgent.value))
const evidence = computed(() => { const output = run.value?.outputs[selectedAgent.value]; if (!output) return ''; const { series, records, ...summary } = output; return JSON.stringify({ ...summary, ...(series ? { hourly_records: series.length, first_record: series[0] } : {}), ...(records ? { forecast_hours: records.length, first_record: records[0] } : {}) }, null, 2) })
const agentName = id => graph.value.nodes.find(n => n.id === id)?.name || id
const statusText = status => ({ completed: '已完成', failed: '执行失败', needs_review: '需复核', running: '执行中' })[status] || status
async function load() { const id = ++requestId; loading.value = true; error.value = ''; try { const res = await api.get('/overview', { params: { ...(day.value ? { day: day.value } : {}), days: section.value === 'carbon' ? days.value : 1 } }); if (id !== requestId) return; data.value = res.data; day.value = res.data.period.end.slice(0, 10); hour.value = Math.min(hour.value, res.data.series.length - 1) } catch (e) { if (id === requestId) error.value = message(e) } finally { if (id === requestId) loading.value = false } }
function message(e) { const detail = e.response?.data?.detail; return typeof detail === 'string' ? detail : detail ? '参数校验失败，请检查输入范围。' : '无法连接分析服务，请确认后端已在 8000 端口启动。' }
function changeDate() { scenario.value = null; stopReplay(); run.value = null; load() }
function toggleTime() { if (timePlaying.value) { clearInterval(timeTimer); timePlaying.value = false } else { timePlaying.value = true; timeTimer = setInterval(() => { hour.value = (hour.value + 1) % data.value.series.length }, 900) } }
function stopReplay() { clearInterval(replayTimer); replaying.value = false }
function toggleReplay() { if (replaying.value) return stopReplay(); if (!run.value) return; if (replayIndex.value >= run.value.events.length) replayIndex.value = 0; replaying.value = true; replayTimer = setInterval(() => { replayIndex.value++; if (replayIndex.value >= run.value.events.length) stopReplay() }, 650) }
async function startRun() { busy.value = true; error.value = ''; stopReplay(); try { run.value = (await api.post('/runs', { day: day.value, strategy: strategy.value })).data; replayIndex.value = 0; toggleReplay(); runs.value = (await api.get('/runs')).data } catch (e) { error.value = message(e) } finally { busy.value = false } }
async function restoreRun(id) { stopReplay(); try { run.value = (await api.get(`/runs/${id}`)).data; replayIndex.value = run.value.events.length } catch (e) { error.value = message(e) } }
function openAgent(id) { selectedAgent.value = id; router.push('/agents') }
const scenarioForm = ref({ strategy: 'balanced', pv_scale: 1, load_scale: 1, capacity_kwh: 5000 }), scenario = ref(null), scenarioBusy = ref(false), lastScenario = ref('')
const scenarioDirty = computed(() => !!scenario.value && lastScenario.value !== JSON.stringify({ day: day.value, ...scenarioForm.value }))
const sliders = [{ key: 'pv_scale', label: '光伏出力倍数', min: .5, max: 2, step: .1, unit: '×' }, { key: 'load_scale', label: '负荷倍数', min: .5, max: 1.5, step: .1, unit: '×' }, { key: 'capacity_kwh', label: '储能容量', min: 0, max: 20000, step: 500, unit: 'kWh' }]
const compareMetrics = [{ key: 'cost_cny', label: '运营成本 / 元', digits: 2 }, { key: 'carbon_t', label: '排放 / tCO₂', digits: 3 }, { key: 'grid_mwh', label: '购电量 / MWh', digits: 2 }, { key: 'self_consumption', label: '就地消纳 / %', digits: 1 }]
async function simulate() { scenarioBusy.value = true; error.value = ''; const payload = { day: day.value, ...scenarioForm.value }; try { const result = (await api.post('/scenario', payload)).data; if (payload.day === day.value) { scenario.value = result; lastScenario.value = JSON.stringify(payload) } } catch (e) { error.value = message(e) } finally { scenarioBusy.value = false } }
const scenarioChart = computed(() => lineChart(scenario.value?.series || [], [{ name: '无储能购电', value: r => Math.max(0, r.load_kw - r.pv_kw - r.wind_kw), dashed: true }, { name: '策略购电', value: r => r.grid_import_kw }]))
const carbonCards = computed(() => { const d = data.value.summary; return [{ title: 'Scope 1 · 直接排放', value: d.scope1_t, unit: 'tCO₂', note: '燃气燃烧 · 演示因子' }, { title: 'Scope 2 · 外购电', value: d.scope2_t, unit: 'tCO₂', note: '购入电量 · 演示因子' }, { title: '用电对应排放强度', value: d.scope2_t / d.load_mwh, unit: 'kg/kWh', note: 'Scope 2 排放 / 园区用电量' }, { title: '中水回用占比', value: d.water_reuse, unit: '%', note: '回用水量 / 总用水量' }] })
const { yAxis: unusedAxis, grid: unusedGrid, ...pieChartBase } = baseChart
const carbonDonut = computed(() => ({ ...pieChartBase, tooltip: { trigger: 'item', valueFormatter: v => number(v, 2) + ' tCO₂' }, series: [{ type: 'pie', radius: ['52%', '73%'], center: ['50%', '45%'], label: { color: '#b3c6b7', formatter: '{b}\n{d}%' }, itemStyle: { borderColor: '#122019', borderWidth: 5 }, data: [{ name: 'Scope 1 燃气', value: data.value.summary.scope1_t }, { name: 'Scope 2 购电', value: data.value.summary.scope2_t }] }] }))
const carbonTrend = computed(() => ({ ...baseChart, xAxis: { type: 'category', data: data.value.daily.map(r => r.date.slice(5)), axisLine: { lineStyle: { color: '#2c4235' } } }, series: [{ name: 'Scope 1', type: 'bar', stack: 'carbon', barMaxWidth: 35, data: data.value.daily.map(r => r.scope1_t) }, { name: 'Scope 2', type: 'bar', stack: 'carbon', barMaxWidth: 35, data: data.value.daily.map(r => r.scope2_t) }] }))
function download(content, name, type) { const url = URL.createObjectURL(new Blob([content], { type })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
function exportData() { const keys = Object.keys(data.value.series[0]); const lines = [keys.join(','), ...data.value.series.map(r => keys.map(k => JSON.stringify(r[k])).join(','))]; download('\ufeff' + lines.join('\r\n'), `simulated-operations-${day.value}.csv`, 'text/csv;charset=utf-8') }
function downloadRun() { download(JSON.stringify(run.value, null, 2), `agent-run-${run.value.id}.json`, 'application/json') }
watch(section, () => { clearInterval(timeTimer); timePlaying.value = false; load() })
onMounted(async () => { await load(); try { const results = await Promise.all([api.get('/agents'), api.get('/runs')]); graph.value = results[0].data; runs.value = results[1].data } catch (e) { error.value = message(e) } })
onBeforeUnmount(() => { ++requestId; clearInterval(timeTimer); stopReplay() })
</script>
